/**
 * Extra anomaly records for the Alien monitor.
 *
 * They come from `public/data/nuforc-recent.json`, a snapshot generated by
 * `npm run sync:nuforc` (scripts/sync-nuforc.mjs) from an open mirror of the
 * NUFORC reports: the mirror is a 19.7 MB CSV and Chromium refuses a JS-set
 * `Range` header, so the tail holding the newest reports is pulled at build
 * time instead of by the browser.
 *
 * Provenance is never hidden: every record keeps the mirror as its source and
 * the UI labels the block, because these are third-party reports and not
 * records published by an agency.
 */

export interface NuforcRecord {
  id: string;
  location: string;
  date_reported: string | null;
  type: string | null;
  severity: string | null;
  description: string | null;
  source: string | null;
  source_url: string | null;
  lat: number | null;
  lon: number | null;
}

interface NuforcSnapshot {
  generatedAt: string;
  source: string;
  sourceUrl: string;
  officialUrl: string;
  totalInTail: number;
  dateFrom: string | null;
  dateTo: string | null;
  records: { date: string; location: string; shape: string | null; duration: string | null; summary: string }[];
}

export const NUFORC_SOURCE = {
  label: "NUFORC (espejo abierto)",
  datasetUrl: "https://github.com/DataHerb/nuforc-ufo-records",
  officialUrl: "https://nuforc.org/",
} as const;

/** Shown next to the registry so the snapshot window is always visible. */
export interface NuforcMeta {
  dateFrom: string | null;
  dateTo: string | null;
  generatedAt: string;
}

let snapshotPromise: Promise<NuforcSnapshot | null> | null = null;

/** Same-origin asset, loaded once per session; a failure just drops the feed. */
function loadSnapshot(): Promise<NuforcSnapshot | null> {
  if (!snapshotPromise) {
    snapshotPromise = fetch("/data/nuforc-recent.json", { signal: AbortSignal.timeout(8000) })
      .then((response) => (response.ok ? (response.json() as Promise<NuforcSnapshot>) : null))
      .catch(() => null);
  }
  return snapshotPromise;
}

/**
 * The newest reports of the snapshot. Resolves to `[]` on any failure: the
 * caller keeps its own records instead of showing an error for a secondary
 * feed.
 */
export async function fetchNuforcRecords(limit = 180): Promise<NuforcRecord[]> {
  const snapshot = await loadSnapshot();
  if (!snapshot?.records?.length) return [];

  return snapshot.records.slice(0, limit).map((record, index) => ({
    id: `nuforc-${record.date}-${index}`,
    location: record.location,
    date_reported: record.date,
    type: record.shape,
    severity: "signal",
    description: [record.summary, record.duration ? `Duración: ${record.duration}` : ""]
      .filter(Boolean)
      .join(" · ")
      .slice(0, 400),
    source: NUFORC_SOURCE.label,
    source_url: NUFORC_SOURCE.datasetUrl,
    lat: null,
    lon: null,
  }));
}

/** Snapshot window, for the provenance line of the registry. */
export async function fetchNuforcMeta(): Promise<NuforcMeta | null> {
  const snapshot = await loadSnapshot();
  if (!snapshot) return null;
  return {
    dateFrom: snapshot.dateFrom,
    dateTo: snapshot.dateTo,
    generatedAt: snapshot.generatedAt,
  };
}
